SELECT recovery_id,direction,source_record_id,business_intent_key,state,attempt_count,next_attempt_at,last_error_code,last_error_summary,dead_lettered_at,recovery_required_at,replay_count,last_replayed_at,last_replayed_by_type,last_replayed_by_id,last_replay_reason,last_replay_correlation_id,resolved_at,lock_version,created_at,updated_at FROM message_recovery WHERE tenant_id=#{tenant}
AND direction=#{direction}
AND state=#{state}
AND dead_lettered_at IS NOT NULLAND dead_lettered_at IS NULL
AND last_error_code=#{error}
AND recovery_required_at >= #{from}
AND recovery_required_at <= #{to}
AND dead_lettered_at IS NOT NULL
 AND (dead_lettered_atrecovery_required_at >  < #{cursor} OR (dead_lettered_atrecovery_required_at=#{cursor} AND recovery_id >  < #{cursorId})) ORDER BY dead_lettered_atrecovery_required_at ASC DESC,recovery_id ASC DESC LIMIT #{limit}
